public without sharing class ContactTriggerHandler {
    public static void onBeforeInsert(List<Contact> newContacts) {
        Map<Id, Account> accountsById = getAccountsById(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    public static void onBeforeUpdate(List<Contact> newContacts) {
        Map<Id, Account> accountsById = getAccountsById(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
        }
    }

    public static void onAfterInsert(List<Contact> newContacts) {
        Map<Id, String> firstPhoneByAccountId = new Map<Id, String>();

        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                if (!firstPhoneByAccountId.containsKey(c.AccountId)) {
                    firstPhoneByAccountId.put(c.AccountId, c.Phone);
                }
            }
        }

        if (firstPhoneByAccountId.isEmpty()) {
            return;
        }

        Set<Id> accountIds = firstPhoneByAccountId.keySet();
        List<Account> accountsToUpdate = new List<Account>();

        for (Account a : [
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            if (String.isBlank(a.Phone)) {
                a.Phone = firstPhoneByAccountId.get(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static Map<Id, Account> getAccountsById(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return new Map<Id, Account>();
        }

        return new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }
}
