public class ExchangeRateClient {
    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final String CURRENCY_PATTERN = '^[A-Z]{3}$';

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (baseCurrency == null) {
            throw new ExchangeRateException('Base currency is required.');
        }

        String normalizedBase = baseCurrency.trim().toUpperCase();
        if (!Pattern.matches(CURRENCY_PATTERN, normalizedBase)) {
            throw new ExchangeRateException('Base currency must be exactly three letters A-Z: ' + baseCurrency);
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            if (quoteCurrency == null) {
                throw new ExchangeRateException('Quote currency cannot be null.');
            }

            String normalizedQuote = quoteCurrency.trim().toUpperCase();
            if (!Pattern.matches(CURRENCY_PATTERN, normalizedQuote)) {
                throw new ExchangeRateException('Quote currency must be exactly three letters A-Z: ' + quoteCurrency);
            }

            normalizedQuotes.add(normalizedQuote);
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();

        String symbolsParam = '';
        for (String quote : sortedQuotes) {
            if (symbolsParam.length() > 0) {
                symbolsParam += ',';
            }
            symbolsParam += quote;
        }

        HttpRequest request = buildRequest(normalizedBase, symbolsParam);
        HttpResponse response = sendRequest(request);

        if (response.getStatusCode() == 503) {
            request = buildRequest(normalizedBase, symbolsParam);
            response = sendRequest(request);
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Exchange rate request failed with HTTP status ' + statusCode + '.');
        }

        return parseRates(response.getBody(), normalizedQuotes);
    }

    private static HttpRequest buildRequest(String baseCurrency, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(
            NAMED_CREDENTIAL_ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(baseCurrency, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8')
        );
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(120000);
        return request;
    }

    private static HttpResponse sendRequest(HttpRequest request) {
        try {
            HttpResponse response = new Http().send(request);
            if (response == null) {
                throw new ExchangeRateException('No response received from exchange rate service.');
            }
            return response;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Callout to exchange rate service failed: ' + e.getMessage());
        }
    }

    private static Map<String, Decimal> parseRates(String responseBody, Set<String> quoteCurrencies) {
        if (responseBody == null || responseBody.trim().length() == 0) {
            throw new ExchangeRateException('Exchange rate response body is empty.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(responseBody);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        Map<String, Object> root;
        try {
            root = (Map<String, Object>) parsed;
        } catch (Exception e) {
            throw new ExchangeRateException('Exchange rate response is not a JSON object.');
        }

        if (root == null) {
            throw new ExchangeRateException('Exchange rate response is not a JSON object.');
        }

        Map<String, Object> rates;
        try {
            rates = (Map<String, Object>) root.get('rates');
        } catch (Exception e) {
            throw new ExchangeRateException('Exchange rate response does not contain a valid rates object.');
        }

        if (rates == null) {
            throw new ExchangeRateException('Exchange rate response does not contain a valid rates object.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quoteCurrency : quoteCurrencies) {
            if (!rates.containsKey(quoteCurrency) || rates.get(quoteCurrency) == null) {
                throw new ExchangeRateException('No exchange rate returned for ' + quoteCurrency + '.');
            }

            Object rateValue = rates.get(quoteCurrency);
            Decimal rate;
            try {
                rate = Decimal.valueOf(String.valueOf(rateValue));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid exchange rate returned for ' + quoteCurrency + '.');
            }

            result.put(quoteCurrency, rate);
        }

        return result;
    }
}
