public with sharing class ContactLookupAction {
    @InvocableMethod(label='Find Contact by Email' description='Finds a Contact by email address, case-insensitively, returning the earliest-created match.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();
        for (Request request : requests) {
            if (request == null) {
                continue;
            }

            String emailKey = normalizeEmail(request.email);
            if (emailKey != null) {
                normalizedEmails.add(emailKey);
            }
        }

        Map<String, Contact> contactByEmail = new Map<String, Contact>();
        if (!normalizedEmails.isEmpty()) {
            List<String> queryEmails = new List<String>(normalizedEmails);

            for (Contact contactRecord : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :queryEmails
                WITH USER_MODE
                ORDER BY CreatedDate ASC
            ]) {
                String emailKey = normalizeEmail(contactRecord.Email);
                if (emailKey != null && !contactByEmail.containsKey(emailKey)) {
                    contactByEmail.put(emailKey, contactRecord);
                }
            }
        }

        for (Request request : requests) {
            Result result = new Result();
            result.found = false;

            if (request != null) {
                String emailKey = normalizeEmail(request.email);
                if (emailKey != null) {
                    Contact matchedContact = contactByEmail.get(emailKey);
                    if (matchedContact != null) {
                        result.found = true;
                        result.contactId = matchedContact.Id;
                    }
                }
            }

            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }

        return email.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
