public class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static OrderPayloadParser.Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('Payload is required');
            }

            Object raw = JSON.deserializeUntyped(body);
            if (!(raw instanceof Map<String, Object>)) {
                throw new PayloadException('Payload must be a JSON object');
            }

            Map<String, Object> root = (Map<String, Object>) raw;

            String orderNumber = asString(root.get('number'));
            if (String.isBlank(orderNumber)) {
                throw new PayloadException('Order number is required');
            }

            String dateText = asString(root.get('date'));
            Date orderDate = null;
            if (!String.isBlank(dateText)) {
                orderDate = Date.valueOf(dateText);
            }

            String currencyCode = asString(root.get('currency'));

            String customerEmail = null;
            Object customerObj = root.get('customer');
            if (customerObj instanceof Map<String, Object>) {
                Map<String, Object> customer = (Map<String, Object>) customerObj;
                customerEmail = asString(customer.get('email'));
            }

            List<Line> lines = new List<Line>();
            Object linesObj = root.get('lines');
            if (linesObj != null) {
                if (!(linesObj instanceof List<Object>)) {
                    throw new PayloadException('lines must be a JSON array');
                }

                List<Object> rawLines = (List<Object>) linesObj;
                for (Object rawLine : rawLines) {
                    if (!(rawLine instanceof Map<String, Object>)) {
                        throw new PayloadException('Each line must be a JSON object');
                    }

                    Map<String, Object> lineMap = (Map<String, Object>) rawLine;

                    String sku = asString(lineMap.get('sku'));
                    if (String.isBlank(sku)) {
                        throw new PayloadException('Line sku is required');
                    }

                    Decimal qtyDec = toDecimal(lineMap.get('quantity'));
                    if (qtyDec == null || qtyDec <= 0) {
                        throw new PayloadException('Line quantity must be positive');
                    }

                    Decimal qtyIntDec = qtyDec.setScale(0, RoundingMode.DOWN);
                    if (qtyDec != qtyIntDec) {
                        throw new PayloadException('Line quantity must be an integer');
                    }
                    Integer quantity = qtyIntDec.intValue();

                    Decimal unitPrice = toDecimal(lineMap.get('unitPrice'));
                    if (unitPrice == null || unitPrice < 0) {
                        throw new PayloadException('Line unitPrice is required and cannot be negative');
                    }

                    Decimal discount = toDecimal(lineMap.get('discount'));
                    if (discount == null) {
                        discount = 0.0;
                    }

                    Decimal lineTotal = quantity * unitPrice * (1 - discount);
                    lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);

                    Line line = new Line();
                    line.sku = sku;
                    line.quantity = quantity;
                    line.unitPrice = unitPrice;
                    line.discount = discount;
                    line.lineTotal = lineTotal;
                    lines.add(line);
                }
            }

            Decimal total = 0.0;
            for (Line line : lines) {
                total = total + line.lineTotal;
            }

            Order order = new Order();
            order.orderNumber = orderNumber;
            order.orderDate = orderDate;
            order.currencyCode = currencyCode;
            order.customerEmail = customerEmail;
            order.lines = lines;
            order.total = total;
            return order;
        } catch (Exception e) {
            if (e instanceof PayloadException) {
                PayloadException pe = (PayloadException) e;
                throw pe;
            }

            String msg = e.getMessage();
            if (String.isBlank(msg)) {
                msg = 'Invalid order payload';
            }
            throw new PayloadException(msg);
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null) {
            throw new PayloadException('Order is required');
        }

        Map<String, Object> result = new Map<String, Object>();
        result.put('number', order.orderNumber);
        result.put('status', 'RECEIVED');
        result.put('lineCount', order.lines == null ? 0 : order.lines.size());
        result.put('total', order.total == null ? 0.0 : order.total);
        return JSON.serialize(result);
    }

    private static String asString(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        return String.valueOf(value);
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if ((value instanceof Integer) || (value instanceof Long) || (value instanceof Double)) {
            return Decimal.valueOf(String.valueOf(value));
        }
        if (value instanceof String) {
            String s = (String) value;
            if (String.isBlank(s)) {
                return null;
            }
            try {
                return Decimal.valueOf(s.trim());
            } catch (Exception e) {
                throw new PayloadException('Invalid numeric value: ' + s);
            }
        }
        throw new PayloadException('Expected numeric value');
    }
}
