public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new LeadImportService.ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Set<String> seenEmails = new Set<String>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> inputIndexes = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead is null');
                continue;
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            String normalizedEmail = null;
            if (lead.Email != null) {
                String trimmedEmail = lead.Email.trim();
                if (trimmedEmail.length() > 0) {
                    normalizedEmail = trimmedEmail.toLowerCase();
                }
            }

            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            leadsToInsert.add(lead);
            inputIndexes.add(i);
        }

        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult saveResult = saveResults[j];
                Integer inputIndex = inputIndexes[j];

                if (saveResult.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(saveResult.getId());
                } else {
                    result.errorsByIndex.put(inputIndex, joinErrors(saveResult.getErrors()));
                }
            }
        }

        return result;
    }

    private static String joinErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'Unknown error';
        }

        String message = '';
        for (Database.Error error : errors) {
            if (message.length() > 0) {
                message += '; ';
            }
            message += error.getMessage();
        }
        return message;
    }
}
