        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (objectApiName == null || String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name is required.');
            }

            if (fieldApiName == null || String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name is required.');
            }

            String normalizedObjectName = objectApiName.trim();
            String normalizedFieldName = fieldApiName.trim();

            Schema.SObjectType sObjectType = findSObjectType(normalizedObjectName);
            if (sObjectType == null) {
                throw new PicklistServiceException('Object does not exist: ' + normalizedObjectName);
            }

            Schema.SObjectField sObjectField = findField(sObjectType, normalizedFieldName);
            if (sObjectField == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + normalizedObjectName + ': ' + normalizedFieldName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();

            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' +
                    normalizedObjectName + '.' + normalizedFieldName
                );
            }

            List<PicklistService.Option> options = new List<PicklistService.Option>();

            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry.isActive()) {
                    options.add(new PicklistService.Option(
                        entry.getValue(),
                        entry.getLabel(),
                        entry.isDefaultValue()
                    ));
                }
            }

            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException('Unable to read picklist values: ' + e.getMessage());
        }
    }

    private static Schema.SObjectType findSObjectType(String objectName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        for (String key : globalDescribe.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectName)) {
                return globalDescribe.get(key);
            }
        }

        return null;
    }

    private static Schema.SObjectField findField(Schema.SObjectType sObjectType, String fieldName) {
        Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();

        for (String key : fieldMap.keySet()) {
            if (key != null && key.equalsIgnoreCase(fieldName)) {
                return fieldMap.get(key);
            }
        }

        return null;
    }
}
