public with sharing class AccountScoringJob implements Queueable {
    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        List<Id> ids = this.accountIds;
        if (ids == null || ids.isEmpty()) {
            return;
        }

        Integer chunkSize = ids.size() > 200 ? 200 : ids.size();
        List<Id> chunk = new List<Id>();
        for (Integer i = 0; i < chunkSize; i++) {
            chunk.add(ids[i]);
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :chunk
        ];

        for (Account acct : accounts) {
            if (acct.AnnualRevenue == null || acct.AnnualRevenue < 100000) {
                acct.Rating = 'Cold';
            } else if (acct.AnnualRevenue < 1000000) {
                acct.Rating = 'Warm';
            } else {
                acct.Rating = 'Hot';
            }
        }

        update accounts;

        if (ids.size() > 200) {
            List<Id> remaining = new List<Id>();
            for (Integer i = 200; i < ids.size(); i++) {
                remaining.add(ids[i]);
            }
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
