public without sharing class OpportunityPipelineHandler {
    // Prevents the legacy AccountTrigger opportunity update from re-entering
    // this handler while we are already updating Account summary fields.
    private static Boolean isUpdatingAccounts = false;

    /**
     * Recalculates the open pipeline fields on every affected Account.
     *
     * Trigger.new is null on delete. Trigger.old is null on insert/undelete.
     * On update both are supplied, which covers amount/stage changes and
     * AccountId moves (the old and new Account are both recalculated).
     */
    public static void handle(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        if (isUpdatingAccounts) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();

        if (newOpps != null) {
            for (Opportunity opp : newOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        if (oldOpps != null) {
            for (Opportunity opp : oldOpps) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount), COUNT(Id)
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal pipeline = (Decimal) ar.get('expr0');
            Integer openCount = (Integer) ar.get('expr1');

            pipelineByAccount.put(accountId, pipeline == null ? 0 : pipeline);
            openCountByAccount.put(accountId, openCount == null ? 0 : openCount);
        }

        Map<Id, Account> existingAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            Account existing = existingAccounts.get(accountId);
            if (existing == null) {
                continue;
            }

            Decimal targetPipeline = pipelineByAccount.containsKey(accountId)
                ? pipelineByAccount.get(accountId)
                : 0;
            Integer targetOpenCount = openCountByAccount.containsKey(accountId)
                ? openCountByAccount.get(accountId)
                : 0;

            if (targetPipeline == null) {
                targetPipeline = 0;
            }
            if (targetOpenCount == null) {
                targetOpenCount = 0;
            }

            // Only update when something actually changed. This also avoids
            // unnecessary AccountTrigger runs on every Opportunity update.
            if (existing.FB_Open_Pipeline__c != targetPipeline ||
                existing.FB_Open_Opportunities__c != targetOpenCount) {
                accountsToUpdate.add(new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = targetPipeline,
                    FB_Open_Opportunities__c = targetOpenCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            isUpdatingAccounts = true;
            try {
                update accountsToUpdate;
            } finally {
                isUpdatingAccounts = false;
            }
        }
    }
}
