public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {
    private static final Integer NORMAL_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer BATCH_SIZE = 2000;
    private static final Integer MAX_DIRECT_DELETE = 10000;
    private static final Integer DIRECT_DELETE_QUERY_LIMIT = MAX_DIRECT_DELETE + 1;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        DateTime normalCutoff = System.now().addDays(-NORMAL_RETENTION_DAYS);
        DateTime errorCutoff = System.now().addDays(-ERROR_RETENTION_DAYS);
        Integer queryLimit = DIRECT_DELETE_QUERY_LIMIT;

        List<FB_Integration_Log__c> logs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :normalCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            LIMIT :queryLimit
        ];

        if (logs.size() <= MAX_DIRECT_DELETE) {
            if (!logs.isEmpty()) {
                Database.delete(logs, false);
            }
        } else {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime normalCutoff = System.now().addDays(-NORMAL_RETENTION_DAYS);
        DateTime errorCutoff = System.now().addDays(-ERROR_RETENTION_DAYS);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :normalCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (!scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    public void finish(Database.BatchableContext bc) {
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }
}
