public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> requestedAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                requestedAccountIds.add(accountId);
                result.put(accountId, 0);
            }
        }

        if (requestedAccountIds.isEmpty()) {
            return result;
        }

        Date today = Date.today();
        Date startOfYear = Date.newInstance(today.year(), 1, 1);
        Date endOfYear = Date.newInstance(today.year(), 12, 31);

        for (AggregateResult row : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :requestedAccountIds
              AND CloseDate >= :startOfYear
              AND CloseDate <= :endOfYear
            WITH USER_MODE
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) row.get('AccountId');
            Decimal totalAmount = (Decimal) row.get('totalAmount');

            if (accountId != null && result.containsKey(accountId)) {
                result.put(accountId, totalAmount == null ? 0 : totalAmount);
            }
        }

        return result;
    }
}
