        Application.UnitOfWork.setMock(mockUow);

        Date cutoff = Date.newInstance(2024, 6, 1);

        Opportunity staleOne = makeOpportunity('Stale One', 'Prospecting', cutoff.addDays(-1));
        Opportunity staleTwo = makeOpportunity('Stale Two', 'Qualification', cutoff.addDays(-10));
        Opportunity onCutoff = makeOpportunity('On Cutoff', 'Prospecting', cutoff);
        Opportunity afterCutoff = makeOpportunity('After Cutoff', 'Prospecting', cutoff.addDays(1));
        Opportunity closedWon = makeOpportunity('Closed Won', 'Closed Won', cutoff.addDays(-1));
        Opportunity closedLost = makeOpportunity('Closed Lost', 'Closed Lost', cutoff.addDays(-1));
        Opportunity noCloseDate = makeOpportunity('No Close Date', 'Prospecting', null);

        List<Opportunity> opportunities = new List<Opportunity>{
            staleOne,
            staleTwo,
            onCutoff,
            afterCutoff,
            closedWon,
            closedLost,
            noCloseDate
        };

