        System.assertEquals(null, afterCutoff.Description);
        System.assertEquals('Closed Won', closedWon.StageName, 'Already closed opportunities are not stale');
        System.assertEquals(null, closedWon.Description);
        System.assertEquals('Closed Lost', closedLost.StageName, 'Already closed opportunities are not stale');
        System.assertEquals(null, closedLost.Description);
