public with sharing class ContactEmailMatcher {
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Set<String> normalizedEmails = new Set<String>();

        for (Request req : requests) {
            if (req != null && String.isNotBlank(req.email)) {
                normalizedEmails.add(normalize(req.email));
            }
        }

        Map<String, Id> firstContactByEmail = new Map<String, Id>();

        if (!normalizedEmails.isEmpty()) {
            for (Contact contactRecord : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(contactRecord.Email);

                if (key != null && !firstContactByEmail.containsKey(key)) {
                    firstContactByEmail.put(key, contactRecord.Id);
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();

            if (req != null && String.isNotBlank(req.email)) {
                res.contactId = firstContactByEmail.get(normalize(req.email));
            }

            results.add(res);
        }

        return results;
    }

    private static String normalize(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }
}
