public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        Set<Id> validContactIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                validContactIds.add(contactId);
            }
        }

        if (validContactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :validContactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contactRecord : contacts) {
            if (String.isNotBlank(contactRecord.Phone)) {
                contactRecord.Phone = contactRecord.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contactRecord);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return errorsByContactId;
        }

        Database.SaveResult[] saveResults = Database.update(contactsToUpdate, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saveResult = saveResults[i];

            if (!saveResult.isSuccess()) {
                String firstErrorMessage = '';
                if (!saveResult.getErrors().isEmpty()) {
                    firstErrorMessage = saveResult.getErrors()[0].getMessage();
                }

                errorsByContactId.put(contactsToUpdate[i].Id, firstErrorMessage);
            }
        }

        return errorsByContactId;
    }
}
