public with sharing class PipelineSummary {
    // Four fixed aggregate queries as requested. A single GROUP BY query would
    // also work, but it adds mapping complexity for no benefit while the stage
    // list is fixed at exactly four values.
    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stageName : STAGES) {
            totals.put(stageName, 0);
        }

        if (fromDate == null || toDate == null) {
            return totals;
        }

        for (String stageName : STAGES) {
            List<AggregateResult> results = [
                SELECT SUM(Amount) total
                FROM Opportunity
                WHERE StageName = :stageName
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
                WITH SECURITY_ENFORCED
            ];

            if (results.size() > 0) {
                Object total = results[0].get('total');
                if (total != null) {
                    totals.put(stageName, (Decimal) total);
                }
            }
        }

        return totals;
    }
}
