public class CasePriorityHandler {
    public static void handleBeforeInsert(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accountsById = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>([
                SELECT Id, Rating
                FROM Account
                WHERE Id IN :accountIds
            ]);
        }

        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }

            Account acct = accountsById.get(c.AccountId);
            if (acct != null && acct.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
