/**
 * Creates one follow-up Task per Opportunity for the weekly pipeline review.
 *
 * Deviation from the per-record try/catch approach: 150-250 per-record DML
 * statements would exceed the synchronous DML statement limit (150). This
 * implementation uses one bulk Database.insert with allOrNone=false, which
 * isolates validation-rule failures per Task and lets successful Tasks commit.
 * Failed SaveResults are mapped back to Opportunity Ids.
 */
public with sharing class FollowUpTaskService {
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Set<Id> requestedOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                requestedOpportunityIds.add(opportunityId);
            }
        }

        if (requestedOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :requestedOpportunityIds
            WITH USER_MODE
        ];

        List<Task> tasksToInsert = new List<Task>();
        List<Id> taskOpportunityIds = new List<Id>();
        Set<Id> foundOpportunityIds = new Set<Id>();

        for (Opportunity opportunity : opportunities) {
            foundOpportunityIds.add(opportunity.Id);

            tasksToInsert.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = Date.today().addDays(7),
                Status = 'Not Started',
                Priority = 'Normal'
            ));

            taskOpportunityIds.add(opportunity.Id);
        }

        // Any requested Opportunity that was not visible/found cannot have a
        // Task created for it.
        for (Id requestedOpportunityId : requestedOpportunityIds) {
            if (!foundOpportunityIds.contains(requestedOpportunityId)) {
                failedOpportunityIds.add(requestedOpportunityId);
            }
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Database.SaveResult> saveResults = Database.insert(
            tasksToInsert,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(taskOpportunityIds[i]);
            }
        }

        return failedOpportunityIds;
    }
}
