trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (oldCase == null) {
            continue;
        }

        if (c.IsClosed && !oldCase.IsClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // Normal bulk close: one Queueable per case.
    if (newlyClosedCaseIds.size() <= CaseSurveyJob.MAX_JOBS_PER_TRANSACTION) {
        for (Id caseId : newlyClosedCaseIds) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }
        return;
    }

    // Large bulk close (e.g. 200 via API): a single transaction cannot enqueue
    // more than 50 Queueables, so enqueue chunked fan-out jobs. Each fan-out job
    // then enqueues one per-case CaseSurveyJob, preserving per-case isolation.
    for (Integer i = 0; i < newlyClosedCaseIds.size(); i += CaseSurveyJob.MAX_JOBS_PER_TRANSACTION) {
        Integer endIndex = Math.min(i + CaseSurveyJob.MAX_JOBS_PER_TRANSACTION, newlyClosedCaseIds.size());
        List<Id> chunk = new List<Id>();

        for (Integer j = i; j < endIndex; j++) {
            chunk.add(newlyClosedCaseIds[j]);
        }

        System.enqueueJob(new CaseSurveyJob(chunk));
    }
}
