public with sharing class CaseSurveyJob implements Queueable {
    public static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    private final Id caseId;
    private final List<Id> fanOutCaseIds;

    // Per-case job.
    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
        this.fanOutCaseIds = null;
    }

    // Fan-out job: enqueues one per-case job for each Id in the provided list.
    // The trigger passes at most MAX_JOBS_PER_TRANSACTION Ids per fan-out job.
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseId = null;
        this.fanOutCaseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseId != null) {
            createSurveyTask(caseId);
            return;
        }

        if (fanOutCaseIds == null || fanOutCaseIds.isEmpty()) {
            return;
        }

        for (Id id : fanOutCaseIds) {
            if (id != null) {
                System.enqueueJob(new CaseSurveyJob(id));
            }
        }
    }

    private void createSurveyTask(Id caseId) {
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];

        // Defensive check: the trigger already filters these out.
        if (c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }
}
