/**
 * RenewalReminderService
 *
 * NOTE: Calling Messaging.sendEmail once per opportunity is not bulk-safe.
 * Apex limits sendEmail invocations to 10 per transaction, so a 200-opportunity
 * job would fail after 10 reminders. This implementation builds all messages
 * and sends them in a single call with allOrNothing=false. That still isolates
 * failures: each SendEmailResult is checked individually, and one failed email
 * does not prevent the others from being sent.
 */
public with sharing class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> ids = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null) {
                ids.add(oppId);
            }
        }

        if (ids.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId, CloseDate
            FROM Opportunity
            WHERE Id IN :ids
        ];

        List<Messaging.Email> emails = new List<Messaging.Email>();

        for (Opportunity opp : opportunities) {
            if (opp.OwnerId == null) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = opp.CloseDate != null
                ? opp.CloseDate.format()
                : 'not set';

            mail.setPlainTextBody(
                'The renewal for opportunity "' + opp.Name + '" is due. ' +
                'Close date: ' + closeDateText + '.'
            );

            emails.add(mail);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        Integer sent = 0;

        try {
            Messaging.SendEmailResult[] results = Messaging.sendEmail(emails, false);

            if (results != null) {
                for (Messaging.SendEmailResult result : results) {
                    if (result != null && result.isSuccess()) {
                        sent++;
                    }
                }
            }
        } catch (Exception e) {
            // If the entire call fails (for example, a global email limit),
            // no reliable per-message result is available. Return the count
            // of confirmed successes.
            return sent;
        }

        return sent;
    }
}
