/**
 * Syncs Contact.MailingCountry when Account.BillingCountry changes.
 *
 * Deviation from the suggested "load all contacts into a map" approach:
 * the org has ~2.3M contacts. A single [SELECT ... FROM Contact] would exceed
 * the synchronous SOQL row limit (50,000) and heap limits, so it is not
 * bulk-safe. This handler still uses exactly one SOQL query, but scopes it to
 * contacts on the accounts in the current trigger batch whose BillingCountry
 * changed, and pre-filters to blank or potentially relevant previous-country
 * values. Final per-account matching is done in memory.
 */
public with sharing class AccountCountrySync {
    public static void handleAfterUpdate(List<Account> newAccounts, Map<Id, Account> oldMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldMap == null) {
            return;
        }

        Map<Id, String> newCountryByAccountId = new Map<Id, String>();
        Map<Id, String> oldCountryByAccountId = new Map<Id, String>();
        Set<Id> changedAccountIds = new Set<Id>();
        Set<String> oldNonBlankCountries = new Set<String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldMap.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }

            String oldCountry = oldAccount.BillingCountry;
            String newCountry = newAccount.BillingCountry;

            if (isSameCountry(oldCountry, newCountry)) {
                continue;
            }

            changedAccountIds.add(newAccount.Id);
            oldCountryByAccountId.put(newAccount.Id, oldCountry);
            newCountryByAccountId.put(newAccount.Id, newCountry);

            if (String.isNotBlank(oldCountry)) {
                oldNonBlankCountries.add(oldCountry);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
              AND (
                  MailingCountry = null
                  OR MailingCountry = ''
                  OR MailingCountry IN :oldNonBlankCountries
              )
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : contacts) {
            String previousCountry = oldCountryByAccountId.get(contactRecord.AccountId);

            if (String.isBlank(contactRecord.MailingCountry)
                    || contactRecord.MailingCountry == previousCountry) {
                contactRecord.MailingCountry = newCountryByAccountId.get(contactRecord.AccountId);
                contactsToUpdate.add(contactRecord);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    private static Boolean isSameCountry(String oldCountry, String newCountry) {
        if (String.isBlank(oldCountry) && String.isBlank(newCountry)) {
            return true;
        }

        return oldCountry == newCountry;
    }
}
