import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import ACCOUNT_NAME_FIELD from '@salesforce/schema/Account.Name';
import ACCOUNT_INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ACCOUNT_ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import ACCOUNT_OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    ACCOUNT_NAME_FIELD,
    ACCOUNT_INDUSTRY_FIELD,
    ACCOUNT_ANNUAL_REVENUE_FIELD,
    ACCOUNT_OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord;

    get recordData() {
        return this.wiredRecord && this.wiredRecord.data;
    }

    get recordError() {
        return this.wiredRecord && this.wiredRecord.error;
    }

    get isLoading() {
        return !this.recordData && !this.recordError;
    }

    get hasError() {
        return Boolean(this.recordError);
    }

    get errorMessage() {
        return this.recordError && this.recordError.body
            ? this.recordError.body.message
            : '';
    }

    get accountName() {
        return this.recordData
            ? getFieldValue(this.recordData, ACCOUNT_NAME_FIELD)
            : '';
    }

    get industry() {
        return this.recordData
            ? getFieldValue(this.recordData, ACCOUNT_INDUSTRY_FIELD)
            : '';
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return this.recordData
            ? getFieldValue(this.recordData, ACCOUNT_ANNUAL_REVENUE_FIELD)
            : null;
    }

    get ownerName() {
        return this.recordData
            ? getFieldValue(this.recordData, ACCOUNT_OWNER_NAME_FIELD)
            : '';
    }
}
