```js
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;
    _debounceTimeout;
    _requestId = 0;
    _isConnected = false;

    connectedCallback() {
        this._isConnected = true;
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._requestId += 1;
        this.clearDebounceTimeout();
    }

    handleSearchChange(event) {
        const rawValue = event.detail?.value ?? event.target?.value ?? '';
        const searchTerm = rawValue.trim();

        this.clearDebounceTimeout();
        this._requestId += 1;
        this.error = undefined;

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            return;
        }

        const requestId = this._requestId;
        this._debounceTimeout = setTimeout(() => {
            this._debounceTimeout = undefined;
            this.performSearch(searchTerm, requestId);
        }, DEBOUNCE_DELAY);
    }

    clearDebounceTimeout() {
        if (this._debounceTimeout !== undefined) {
            window.clearTimeout(this._debounceTimeout);
            this._debounceTimeout = undefined;
        }
    }

    async performSearch(searchTerm, requestId) {
        if (!this._isConnected || requestId !== this._requestId) {
            return;
        }

        try {
            const results = await searchContacts({ searchTerm });

            if (!this._isConnected || requestId !== this._requestId) {
                return;
            }

            this.contacts = results || [];
            this.error = undefined;
        } catch (error) {
            if (!this._isConnected || requestId !== this._requestId) {
                return;
            }

            this.contacts = [];
            this.error = error?.body?.message ?? 'An error occurred while searching contacts.';
        }
    }
}
