    submitAll() {
        const editors = this.getEditors();
        let allValid = true;

        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (!allValid) {
            this.hasError = true;
            return;
        }

        this.hasError = false;

        const lines = editors.map((editor) => editor.getValue());
        this.dispatchEvent(
            new CustomEvent('submit', {
                detail: { lines }
            })
        );
    }

    getEditors() {
        return Array.from(this.template.querySelectorAll('c-line-item-editor'));
    }
}
