import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;
const DEFAULT_ERROR_MESSAGE = 'Unable to load queue statistics.';

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _pollTimer;
    _pollId = 0;
    _isConnected = false;
    _inFlight = false;
    _requestId = 0;

    constructor() {
        super();
        this._visibilityHandler = this.handleVisibilityChange.bind(this);
    }

    connectedCallback() {
        this._isConnected = true;
        document.removeEventListener('visibilitychange', this._visibilityHandler);
        document.addEventListener('visibilitychange', this._visibilityHandler);
        this.startPolling();
    }

    disconnectedCallback() {
        this._isConnected = false;
        this._requestId += 1;
        document.removeEventListener('visibilitychange', this._visibilityHandler);
        this.stopPolling();
        this._inFlight = false;
    }

    startPolling() {
        this.stopPolling();

        if (!this._isConnected || document.visibilityState === 'hidden') {
            return;
        }

        const pollId = ++this._pollId;

        this.loadStats();

        this._pollTimer = window.setInterval(() => {
            if (
                pollId !== this._pollId ||
                !this._isConnected ||
                document.visibilityState === 'hidden'
            ) {
                return;
            }

            this.loadStats();
        }, POLL_INTERVAL_MS);
    }

    stopPolling() {
        this._pollId += 1;

        if (this._pollTimer !== undefined) {
            window.clearInterval(this._pollTimer);
            this._pollTimer = undefined;
        }
    }

    handleVisibilityChange() {
        if (!this._isConnected) {
            return;
        }

        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            this.startPolling();
        }
    }

    async loadStats() {
        if (
            !this._isConnected ||
            document.visibilityState === 'hidden' ||
            this._inFlight
        ) {
            return;
        }

        this._inFlight = true;
        const requestId = ++this._requestId;

        try {
            const result = await getQueueStats();

            if (!this._isConnected || requestId !== this._requestId) {
                return;
            }

            this.stats = result;
            this.errorMessage = undefined;
        } catch (error) {
            if (!this._isConnected || requestId !== this._requestId) {
                return;
            }

            this.errorMessage =
                error && error.body && error.body.message
                    ? error.body.message
                    : DEFAULT_ERROR_MESSAGE;
        } finally {
            if (requestId === this._requestId) {
                this._inFlight = false;
            }
        }
    }
