import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const PERSONAL_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    formData = {
        fullName: '',
        email: '',
        company: ''
    };

    handleChange(event) {
        const field = event.currentTarget.dataset.field;

        this.formData = {
            ...this.formData,
            [field]: event.detail.value
        };
    }

    async handleRegister() {
        const inputs = Array.from(this.template.querySelectorAll('lightning-input'));
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');

        const email = (this.formData.email || '').trim();
        const domain = email.includes('@') ? email.split('@').pop().toLowerCase() : '';

        emailInput.setCustomValidity(
            PERSONAL_EMAIL_DOMAINS.has(domain) ? 'Use your work email address.' : ''
        );

        let allValid = true;

        inputs.forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        try {
            await register({
                fullName: this.formData.fullName,
                email: this.formData.email,
                company: this.formData.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    variant: 'error',
                    message: error.body.message
                })
            );
        }
    }
}
