import { LightningElement, api, track } from 'lwc';

let nextInstanceId = 0;

export default class StatusListbox extends LightningElement {
    @api label = '';

    @track _options = [];
    @track _value = '';
    @track _activeIndex = -1;

    _instanceId;

    constructor() {
        super();
        this._instanceId = `status-listbox-${++nextInstanceId}`;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value.slice() : [];
        this._syncActiveIndexFromValue();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value === undefined || value === null ? '' : value;
        this._syncActiveIndexFromValue();
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            id: this._optionId(index),
            index,
            value: option.value,
            label: option.label,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            return '';
        }

        return this._optionId(this._activeIndex);
    }

    handleKeydown(event) {
        const key = event.key;
        const isHandledKey =
            key === 'ArrowDown' ||
            key === 'ArrowUp' ||
            key === 'Home' ||
            key === 'End' ||
            key === 'Enter' ||
            key === ' ';

        if (isHandledKey) {
            event.preventDefault();
        }

        if (!this._options.length) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                this._setActiveIndex(this._activeIndex + 1);
                break;
            case 'ArrowUp':
                this._setActiveIndex(this._activeIndex - 1);
                break;
            case 'Home':
                this._setActiveIndex(0);
                break;
            case 'End':
                this._setActiveIndex(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                this._selectIndex(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }

        this._setActiveIndex(index);
        this._selectIndex(index);

        const list = this.template.querySelector('ul[role="listbox"]');
        if (list) {
            list.focus();
        }
    }

    _syncActiveIndexFromValue() {
        if (!this._options.length) {
            this._activeIndex = -1;
            return;
        }

        const selectedIndex = this._options.findIndex(
            (option) => option && option.value === this._value
        );

        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    _setActiveIndex(index) {
        if (!this._options.length) {
            return;
        }

        const lastIndex = this._options.length - 1;
        this._activeIndex = Math.min(Math.max(index, 0), lastIndex);
    }

    _selectIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }

        const nextValue = this._options[index].value;

        if (nextValue === this._value) {
            return;
        }

        this._value = nextValue;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: nextValue },
                bubbles: true,
                composed: true
            })
        );
    }

    _optionId(index) {
        return `${this._instanceId}-option-${index}`;
    }
}
