import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this.copyTasks(this.items);
    }

    set tasks(value) {
        this.items = this.copyTasks(value);
    }

    get displayHeading() {
        return this.heading == null ? '' : String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    copyTasks(value) {
        return Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];
    }

    handleLabelChange(event) {
        let value = '';
        if (event.detail && event.detail.value !== undefined) {
            value = event.detail.value;
        } else if (event.target) {
            value = event.target.value;
        }
        this.newLabel = value == null ? '' : value;
    }

    handleAdd() {
        const label = this.newLabel == null ? '' : String(this.newLabel).trim();
        if (!label) {
            return;
        }

        const task = {
            id: this.generateId(),
            label,
            done: false
        };

        this.items = [...this.items, task];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const target = event.currentTarget || event.target;
        const id = target.dataset.id;
        this.items = this.items.map((task) =>
            String(task.id) === String(id) ? { ...task, done: !task.done } : task
        );
    }

    generateId() {
        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));
        return id;
    }
}
