public with sharing class EmployerService {
    private static final String STATUS_CURRENT = 'Current';

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Map<Id, Id> requestedByContactId = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<Id> organizationIds = new Set<Id>();

        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);
            if (contactId != null && organizationId != null) {
                requestedByContactId.put(contactId, organizationId);
                contactIds.add(contactId);
                organizationIds.add(organizationId);
            }
        }

        if (requestedByContactId.isEmpty()) {
            return;
        }

        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, AccountId, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]);

        if (contactsById.isEmpty()) {
            return;
        }

        Set<Id> existingContactIds = contactsById.keySet();

        Map<Id, Map<Id, npe5__Affiliation__c>> affiliationByContactIdAndOrgId =
            new Map<Id, Map<Id, npe5__Affiliation__c>>();

        for (npe5__Affiliation__c affiliation : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c,
                   npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :existingContactIds
              AND npe5__Organization__c IN :organizationIds
            WITH USER_MODE
        ]) {
            if (affiliation.npe5__Contact__c == null || affiliation.npe5__Organization__c == null) {
                continue;
            }

            Map<Id, npe5__Affiliation__c> byOrgId =
                affiliationByContactIdAndOrgId.get(affiliation.npe5__Contact__c);

            if (byOrgId == null) {
                byOrgId = new Map<Id, npe5__Affiliation__c>();
                affiliationByContactIdAndOrgId.put(affiliation.npe5__Contact__c, byOrgId);
            }

            npe5__Affiliation__c existing = byOrgId.get(affiliation.npe5__Organization__c);
            if (existing == null
                || (affiliation.npe5__Status__c == STATUS_CURRENT
                    && affiliation.npe5__Primary__c == true)) {
                byOrgId.put(affiliation.npe5__Organization__c, affiliation);
            }
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToUpsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : requestedByContactId.keySet()) {
            Contact contactRecord = contactsById.get(contactId);
            if (contactRecord == null) {
                continue;
            }

            Id organizationId = requestedByContactId.get(contactId);

            npe5__Affiliation__c targetAffiliation = null;
            Map<Id, npe5__Affiliation__c> byOrgId = affiliationByContactIdAndOrgId.get(contactId);
            if (byOrgId != null) {
                targetAffiliation = byOrgId.get(organizationId);
            }

            if (targetAffiliation != null
                && targetAffiliation.npe5__Status__c == STATUS_CURRENT
                && targetAffiliation.npe5__Primary__c == true) {
                if (contactRecord.npsp__Primary_Affiliation__c != organizationId) {
                    contactRecord.npsp__Primary_Affiliation__c = organizationId;
                    contactsToUpdate.add(contactRecord);
                }
                continue;
            }

            if (targetAffiliation == null) {
                targetAffiliation = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = organizationId
                );
            }

            targetAffiliation.npe5__Status__c = STATUS_CURRENT;
            targetAffiliation.npe5__Primary__c = true;

            if (targetAffiliation.npe5__StartDate__c == null) {
                targetAffiliation.npe5__StartDate__c = today;
            }

            targetAffiliation.npe5__EndDate__c = null;
            affiliationsToUpsert.add(targetAffiliation);

            if (contactRecord.npsp__Primary_Affiliation__c != organizationId) {
                contactRecord.npsp__Primary_Affiliation__c = organizationId;
                contactsToUpdate.add(contactRecord);
            }
        }

        if (!affiliationsToUpsert.isEmpty()) {
            Database.upsert(affiliationsToUpsert, AccessLevel.USER_MODE);
        }

        if (!contactsToUpdate.isEmpty()) {
            Database.update(contactsToUpdate, AccessLevel.USER_MODE);
        }
    }
}
