public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            results.add(result);
        }

        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        List<Integer> dataImportIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];

            if (gift == null) {
                results[i].errorMessage = 'Gift is null.';
                continue;
            }

            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift.email;
            dataImport.npsp__Donation_Amount__c = gift.amount;
            dataImport.npsp__Donation_Date__c = gift.giftDate;
            dataImport.npsp__Donation_Donor__c = 'Contact1';
            dataImport.npsp__Status__c = 'Ready';

            dataImports.add(dataImport);
            dataImportIndexes.add(i);
        }

        if (dataImports.isEmpty()) {
            return results;
        }

        Database.SaveResult[] insertResults = Database.insert(dataImports, false);
        List<Id> insertedIds = new List<Id>();

        for (Integer i = 0; i < insertResults.size(); i++) {
            Database.SaveResult saveResult = insertResults[i];
            Integer resultIndex = dataImportIndexes[i];

            if (saveResult.isSuccess()) {
                insertedIds.add(saveResult.getId());
            } else {
                results[resultIndex].errorMessage = saveResult.getErrors()[0].getMessage();
            }
        }

        if (!insertedIds.isEmpty()) {
            npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();

            npsp.DataImport dataImportApi = new npsp.DataImport();
            if (settings != null) {
                dataImportApi.setDataImportSettings(settings);
            }

            try {
                dataImportApi.run();
            } catch (Exception ex) {
                // The API may throw before or during processing. We still query the
                // Data Import records below to build results from their final state.
                for (Integer i = 0; i < dataImports.size(); i++) {
                    npsp__DataImport__c dataImport = dataImports[i];
                    Integer resultIndex = dataImportIndexes[i];

                    if (dataImport.Id != null && String.isBlank(results[resultIndex].errorMessage)) {
                        results[resultIndex].errorMessage = ex.getMessage();
                    }
                }
            }

            Map<Id, npsp__DataImport__c> processedDataImports = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :insertedIds
            ]);

            for (Integer i = 0; i < dataImports.size(); i++) {
                npsp__DataImport__c dataImport = dataImports[i];
                Integer resultIndex = dataImportIndexes[i];

                if (dataImport.Id == null) {
                    continue;
                }

                npsp__DataImport__c processedDataImport = processedDataImports.get(dataImport.Id);
                if (processedDataImport == null) {
                    if (String.isBlank(results[resultIndex].errorMessage)) {
                        results[resultIndex].errorMessage = 'NPSP Data Import record was not processed.';
                    }
                    continue;
                }

                results[resultIndex].contactId = processedDataImport.npsp__Contact1Imported__c;
                results[resultIndex].opportunityId = processedDataImport.npsp__DonationImported__c;

                if (processedDataImport.npsp__Status__c == 'Imported') {
                    results[resultIndex].success = true;
                    results[resultIndex].errorMessage = null;
                } else {
                    results[resultIndex].success = false;
                    results[resultIndex].errorMessage = processedDataImport.npsp__FailureInformation__c;

                    if (String.isBlank(results[resultIndex].errorMessage)) {
                        results[resultIndex].errorMessage =
                            'NPSP Data Import status: ' + processedDataImport.npsp__Status__c;
                    }
                }
            }
        }

        return results;
    }
}
