public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal totalPercent = 0;

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }

            Decimal percent = percentByGauId.get(gauId);

            if (percent == null || percent <= 0) {
                throw new AllocationException('GAU percentages must be greater than zero.');
            }

            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total GAU percentage cannot exceed 100.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :percentByGauId.keySet()
        ]);

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);

            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('All GAUs must exist and be active.');
            }
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found.');
        }

        Decimal opportunityAmount = opportunities[0].Amount == null ? 0.0 : opportunities[0].Amount;

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);

            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = opportunityAmount * percent / 100
            ));
        }

        insert newAllocations;

        return newAllocations;
