public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact donor = contacts[0];

        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account.');
        }

        String firstName = donor.FirstName == null ? '' : donor.FirstName;
        String lastName = donor.LastName == null ? '' : donor.LastName;
        String opportunityName = (String.isBlank(firstName) ? '' : firstName + ' ')
            + lastName
            + ' Donation '
            + giftDate.format('yyyy-MM-dd');

        Opportunity gift = new Opportunity(
            Name = opportunityName,
            AccountId = donor.AccountId,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert gift;

        Map<Id, String> desiredRoleByContactId = new Map<Id, String>();
        desiredRoleByContactId.put(donor.Id, 'Donor');

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        for (Contact member : householdMembers) {
            if (member.Id != donor.Id) {
                desiredRoleByContactId.put(member.Id, 'Household Member');
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId = :gift.Id
        ];

        Map<Id, List<OpportunityContactRole>> existingRolesByContactId = new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole role : existingRoles) {
            if (!existingRolesByContactId.containsKey(role.ContactId)) {
                existingRolesByContactId.put(role.ContactId, new List<OpportunityContactRole>());
            }
            existingRolesByContactId.get(role.ContactId).add(role);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        Set<Id> desiredContactIds = desiredRoleByContactId.keySet();

        for (Id roleContactId : desiredContactIds) {
            String desiredRole = desiredRoleByContactId.get(roleContactId);
            List<OpportunityContactRole> existingForContact = existingRolesByContactId.get(roleContactId);

            if (existingForContact == null || existingForContact.isEmpty()) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = gift.Id,
                    ContactId = roleContactId,
                    Role = desiredRole
                ));
            } else {
                OpportunityContactRole keepRole = existingForContact[0];
                if (keepRole.Role != desiredRole) {
                    keepRole.Role = desiredRole;
                    rolesToUpdate.add(keepRole);
                }

                for (Integer i = 1; i < existingForContact.size(); i++) {
                    rolesToDelete.add(existingForContact[i]);
                }
            }
        }

        for (Id roleContactId : existingRolesByContactId.keySet()) {
            if (!desiredContactIds.contains(roleContactId)) {
                rolesToDelete.addAll(existingRolesByContactId.get(roleContactId));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c,
                   npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :gift.Id
            ORDER BY CreatedDate ASC
        ];

        if (existingPayments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = gift.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            insert payment;
        } else {
            List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < existingPayments.size(); i++) {
                paymentsToDelete.add(existingPayments[i]);
            }

            if (!paymentsToDelete.isEmpty()) {
                delete paymentsToDelete;
            }

            npe01__OppPayment__c payment = existingPayments[0];
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            update payment;
        }

        return gift.Id;
    }
}
