public with sharing class FamilyService {
    private static final String RELATIONSHIP_TYPE_PARENT = 'Parent';
    private static final String RELATIONSHIP_STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            childIds.add(childId);
            parentIds.add(parentId);
        }

        if (childIds.isEmpty() || parentIds.isEmpty()) {
            return;
        }

        Map<Id, Set<Id>> existingRelatedContactIdsByContactId = new Map<Id, Set<Id>>();

        for (npe4__Relationship__c relationship : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            addExistingRelationship(
                existingRelatedContactIdsByContactId,
                relationship.npe4__Contact__c,
                relationship.npe4__RelatedContact__c
            );
            addExistingRelationship(
                existingRelatedContactIdsByContactId,
                relationship.npe4__RelatedContact__c,
                relationship.npe4__Contact__c
            );
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            if (hasExistingRelationship(existingRelatedContactIdsByContactId, childId, parentId)) {
                continue;
            }

            // NPSP's reciprocal automation creates the reverse relationship.
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = RELATIONSHIP_TYPE_PARENT,
                npe4__Status__c = RELATIONSHIP_STATUS_CURRENT
            ));

            // Defensive guard against duplicate unordered pairs in the input.
            addExistingRelationship(existingRelatedContactIdsByContactId, childId, parentId);
            addExistingRelationship(existingRelatedContactIdsByContactId, parentId, childId);
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static void addExistingRelationship(
        Map<Id, Set<Id>> existingRelatedContactIdsByContactId,
        Id contactId,
        Id relatedContactId
    ) {
        if (contactId == null || relatedContactId == null) {
            return;
        }

        if (!existingRelatedContactIdsByContactId.containsKey(contactId)) {
            existingRelatedContactIdsByContactId.put(contactId, new Set<Id>());
        }
        existingRelatedContactIdsByContactId.get(contactId).add(relatedContactId);
    }

    private static Boolean hasExistingRelationship(
        Map<Id, Set<Id>> existingRelatedContactIdsByContactId,
        Id contactId,
        Id relatedContactId
    ) {
        return existingRelatedContactIdsByContactId.containsKey(contactId)
            && existingRelatedContactIdsByContactId.get(contactId).contains(relatedContactId);
    }
}
