public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate
            && (oldlist == null || oldlist.size() != newlist.size())) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            if (!(newlist[i] instanceof Opportunity)) {
                continue;
            }

            Opportunity opp = (Opportunity) newlist[i];

            if (!isQualifiedMajorGift(opp)) {
                continue;
            }

            Boolean wasQualified = false;
            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate
                && oldlist[i] instanceof Opportunity) {
                wasQualified = isQualifiedMajorGift((Opportunity) oldlist[i]);
            }

            if (wasQualified) {
                continue;
            }

            tasksToInsert.add(buildFollowUpTask(opp));
        }

        for (Task t : tasksToInsert) {
            dmlWrapper.objectsToInsert.add(t);
        }

        return dmlWrapper;
    }

    private static Boolean isQualifiedMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;

        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }

        return t;
    }
}
