@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    static void rejectsReductionGreaterThanHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = makeOpportunity(oppId, 1000.0);
        Opportunity newOpp = makeOpportunity(oppId, 499.0);

        runBeforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        assertHasSingleError(newOpp);
    }

    @IsTest
    static void acceptsReductionExactlyHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = makeOpportunity(oppId, 1000.0);
        Opportunity newOpp = makeOpportunity(oppId, 500.0);

        runBeforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        assertNoErrors(newOpp);
    }

    @IsTest
    static void acceptsAmountIncrease() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = makeOpportunity(oppId, 1000.0);
        Opportunity newOpp = makeOpportunity(oppId, 1500.0);

        runBeforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        assertNoErrors(newOpp);
    }

    @IsTest
    static void acceptsNullPreviousAmount() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = makeOpportunity(oppId, null);
        Opportunity newOpp = makeOpportunity(oppId, 100.0);

        runBeforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        assertNoErrors(newOpp);
    }

    @IsTest
    static void mixedRecordsOnlyInvalidRowsReceiveErrors() {
        Id invalidId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id invalidId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validId1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validId2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validId3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity invalidOld1 = makeOpportunity(invalidId1, 1000.0);
        Opportunity invalidNew1 = makeOpportunity(invalidId1, 499.0);
        Opportunity invalidOld2 = makeOpportunity(invalidId2, 800.0);
        Opportunity invalidNew2 = makeOpportunity(invalidId2, 399.0);

        Opportunity validOld1 = makeOpportunity(validId1, 1000.0);
        Opportunity validNew1 = makeOpportunity(validId1, 500.0);
        Opportunity validOld2 = makeOpportunity(validId2, 1000.0);
        Opportunity validNew2 = makeOpportunity(validId2, 1500.0);
        Opportunity validOld3 = makeOpportunity(validId3, null);
        Opportunity validNew3 = makeOpportunity(validId3, 50.0);

        runBeforeUpdate(
            new List<Opportunity>{ invalidNew1, validNew1, invalidNew2, validNew2, validNew3 },
            new List<Opportunity>{ invalidOld1, validOld1, invalidOld2, validOld2, validOld3 }
        );

        assertHasSingleError(invalidNew1);
        assertHasSingleError(invalidNew2);
        assertNoErrors(validNew1);
        assertNoErrors(validNew2);
        assertNoErrors(validNew3);
    }

    private static void runBeforeUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
    }

    private static Opportunity makeOpportunity(Id oppId, Decimal amount) {
        return new Opportunity(Id = oppId, Amount = amount);
    }

    private static void assertHasSingleError(Opportunity opp) {
        System.assert(opp.hasErrors(), 'Expected an error on Opportunity ' + opp.Id);
        System.assertEquals(1, opp.getErrors().size(), 'Expected exactly one error on Opportunity ' + opp.Id);
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            opp.getErrors()[0].getMessage(),
            'Expected the guard amount decrease error message on Opportunity ' + opp.Id
        );
    }

    private static void assertNoErrors(Opportunity opp) {
        System.assert(!opp.hasErrors(), 'Did not expect an error on Opportunity ' + opp.Id);
        System.assertEquals(0, opp.getErrors().size(), 'Expected no errors on Opportunity ' + opp.Id);
    }
}
