public inherited sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> newContacts = toContacts(triggerNew);
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : newContacts) {
            if (isCheckable(c)) {
                accountIds.add(c.AccountId);
                emails.add(c.Email);
            }
        }

        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        Set<String> existingKeys = queryExistingKeys(accountIds, emails, new Set<Id>());
        rejectDuplicates(newContacts, existingKeys);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = toContacts(triggerNew);
        Map<Id, Contact> oldById = new Map<Id, Contact>();

        for (SObject record : triggerOld) {
            Contact oldContact = (Contact) record;
            oldById.put(oldContact.Id, oldContact);
        }

        Set<Id> changedIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : newContacts) {
            Contact oldContact = oldById.get(c.Id);
            if (oldContact != null && isRelevantChange(c, oldContact)) {
                changedIds.add(c.Id);
                if (isCheckable(c)) {
                    accountIds.add(c.AccountId);
                    emails.add(c.Email);
                }
            }
        }

        if (accountIds.isEmpty() || emails.isEmpty()) {
            return;
        }

        Set<String> existingKeys = queryExistingKeys(accountIds, emails, changedIds);
        rejectDuplicatesForUpdate(newContacts, oldById, existingKeys);
    }

    private static void rejectDuplicates(List<Contact> contacts, Set<String> existingKeys) {
        Set<String> acceptedKeys = new Set<String>();

        for (Contact c : contacts) {
            if (!isCheckable(c)) {
                continue;
            }

            String key = keyFor(c);
            if (existingKeys.contains(key) || acceptedKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                acceptedKeys.add(key);
            }
        }
    }

    private static void rejectDuplicatesForUpdate(
        List<Contact> contacts,
        Map<Id, Contact> oldById,
        Set<String> existingKeys
    ) {
        Set<String> acceptedKeys = new Set<String>();

        for (Contact c : contacts) {
            Contact oldContact = oldById.get(c.Id);
            if (oldContact == null || !isRelevantChange(c, oldContact) || !isCheckable(c)) {
                continue;
            }

            String key = keyFor(c);
            if (existingKeys.contains(key) || acceptedKeys.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                acceptedKeys.add(key);
            }
        }
    }

    private static Set<String> queryExistingKeys(Set<Id> accountIds, Set<String> emails, Set<Id> excludedIds) {
        Set<String> keys = new Set<String>();

        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email IN :emails
        ]) {
            if (excludedIds.contains(c.Id)) {
                continue;
            }
            if (isCheckable(c)) {
                keys.add(keyFor(c));
            }
        }

        return keys;
    }

    private static Boolean isCheckable(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static String keyFor(Contact c) {
        return String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();
    }

    private static Boolean isRelevantChange(Contact newContact, Contact oldContact) {
        if (newContact.AccountId != oldContact.AccountId) {
            return true;
        }

        String newEmail = newContact.Email == null ? null : newContact.Email.toLowerCase();
        String oldEmail = oldContact.Email == null ? null : oldContact.Email.toLowerCase();
        return newEmail != oldEmail;
    }

    private static List<Contact> toContacts(List<SObject> records) {
        List<Contact> contacts = new List<Contact>();
        for (SObject record : records) {
            contacts.add((Contact) record);
        }
        return contacts;
    }
}
