public with sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        recalculateOpenCaseCounts(getAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = getAccountIds(triggerNew);
        accountIds.addAll(getAccountIds(triggerOld));
        recalculateOpenCaseCounts(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculateOpenCaseCounts(getAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculateOpenCaseCounts(getAccountIds(triggerNew));
    }

    private Set<Id> getAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }
        return accountIds;
    }

    private void recalculateOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> countsByAccountId = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            countsByAccountId.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE IsClosed = false
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Integer openCount = (Integer) result.get('openCount');
            countsByAccountId.put(accountId, openCount);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : countsByAccountId.keySet()) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                FB_Open_Case_Count__c = countsByAccountId.get(accountId)
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
