public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public TA_Contact_InheritMailingAddress() {
    }

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;

            if (contact.AccountId == null) {
                continue;
            }

            Account parentAccount = accountsById.get(contact.AccountId);
            if (parentAccount == null) {
                continue;
            }

            if (String.isBlank(contact.MailingStreet)
                && String.isBlank(contact.MailingCity)
                && String.isBlank(contact.MailingPostalCode)
                && String.isBlank(contact.MailingCountry)) {
                contact.MailingStreet = parentAccount.BillingStreet;
                contact.MailingCity = parentAccount.BillingCity;
                contact.MailingPostalCode = parentAccount.BillingPostalCode;
                contact.MailingCountry = parentAccount.BillingCountry;
            }
        }
    }
}
